{"version":3,"file":"NavHeader.jsdbx","sources":["../../src/client/components/shared/NavHeader.css","../../src/client/components/shared/NavHeader.tsx"],"sourcesContent":[".nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #060911;
  border-bottom: 1px solid var(--cc-border, #1e2a45);
  padding: 0 24px;
  height: 56px;
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-header__left {
  display: flex;
  align-items: center;
}

.nav-header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-header__logo-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--cc-accent, #00c896);
}

.nav-header__logo-text {
  font-size: 16px;
  font-weight: 700;
  color: var(--cc-text-primary, #e2e8f0);
  letter-spacing: -0.3px;
}

.nav-header__logo-divider {
  color: var(--cc-text-secondary, #94a3b8);
  font-weight: 300;
  margin: 0 2px;
}

.nav-header__logo-subtitle {
  font-size: 11px;
  font-weight: 600;
  color: var(--cc-text-secondary, #94a3b8);
  letter-spacing: 1.2px;
  text-transform: uppercase;
}

.nav-header__center {
  display: flex;
  align-items: center;
  gap: 4px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 4px;
}

.nav-header__tab {
  padding: 6px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--cc-text-secondary, #94a3b8);
  text-decoration: none;
  transition: all 0.2s ease;
}

.nav-header__tab:hover {
  color: var(--cc-text-primary, #e2e8f0);
}

.nav-header__tab--active {
  background: #ffffff;
  color: #0a0e1a;
  font-weight: 600;
}

.nav-header__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-header__search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--cc-border, #1e2a45);
  border-radius: 8px;
  padding: 6px 12px;
}

.nav-header__search-icon {
  color: var(--cc-text-secondary, #94a3b8);
  flex-shrink: 0;
}

.nav-header__search-input {
  background: none;
  border: none;
  outline: none;
  color: var(--cc-text-primary, #e2e8f0);
  font-size: 12px;
  width: 180px;
}

.nav-header__search-input::placeholder {
  color: var(--cc-text-secondary, #94a3b8);
}

.nav-header__icon-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: none;
  color: var(--cc-text-secondary, #94a3b8);
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  position: relative;
}

.nav-header__icon-btn:hover {
  color: var(--cc-text-primary, #e2e8f0);
}

.nav-header__badge {
  position: absolute;
  top: 0;
  right: 0;
  background: var(--cc-critical, #ef4444);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-header__calendar-text {
  font-size: 12px;
  color: var(--cc-text-secondary, #94a3b8);
}

.nav-header__avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
}
","import React from 'react';
import './NavHeader.css';

const NAV_TABS = [
  { label: 'Executive', href: '/x_2145749_qc_exec_dashboard.do' },
  { label: 'Operations', href: '/x_2145749_qc_ops_dashboard.do' },
  { label: 'Dark Store', href: '/x_2145749_qc_dark_store_dashboard.do' },
  { label: 'Fraud', href: '/x_2145749_qc_fraud_dashboard.do' },
];

function NavHeader() {
  const currentPath = window.location.pathname;

  return (
    <header className="nav-header">
      <div className="nav-header__left">
        <div className="nav-header__logo">
          <div className="nav-header__logo-icon" />
          <span className="nav-header__logo-text">DarkOps</span>
          <span className="nav-header__logo-divider">|</span>
          <span className="nav-header__logo-subtitle">OPERATIONAL INTELLIGENCE</span>
        </div>
      </div>

      <nav className="nav-header__center">
        {NAV_TABS.map((tab) => {
          const isActive = currentPath.includes(tab.href.replace('.do', ''));
          return (
            <a
              key={tab.label}
              href={tab.href}
              className={`nav-header__tab ${isActive ? 'nav-header__tab--active' : ''}`}
            >
              {tab.label}
            </a>
          );
        })}
      </nav>

      <div className="nav-header__right">
        <div className="nav-header__search">
          <svg className="nav-header__search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <circle cx="11" cy="11" r="8" />
            <path d="M21 21l-4.35-4.35" />
          </svg>
          <input
            type="text"
            placeholder="Search store ID e.g. 1462..."
            className="nav-header__search-input"
          />
        </div>

        <button className="nav-header__icon-btn nav-header__bell">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
            <path d="M13.73 21a2 2 0 0 1-3.46 0" />
          </svg>
          <span className="nav-header__badge">5</span>
        </button>

        <button className="nav-header__icon-btn nav-header__calendar">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
            <line x1="16" y1="2" x2="16" y2="6" />
            <line x1="8" y1="2" x2="8" y2="6" />
            <line x1="3" y1="10" x2="21" y2="10" />
          </svg>
          <span className="nav-header__calendar-text">Last 30 days</span>
        </button>

        <div className="nav-header__avatar">AK</div>
      </div>
    </header>
  );
}

export default NavHeader;
